style.css:
@-moz-document domain("youtube.com") {
/* === HOLLOW KNIGHT SILKSONG YOUTUBE THEME === */
/* Inspired by Team Cherry's Hollow Knight: Silksong */
/* Colors: Deep blues, elegant greens, silvery whites */

:root {
  --silksong-dark-blue: #0a1628;
  --silksong-deep-blue: #1a2845;
  --silksong-accent-blue: #2d4a7c;
  --silksong-green: #3d5a4f;
  --silksong-teal: #4a7c7c;
  --silksong-silver: #c8d3e0;
  --silksong-white: #e8f0f7;
  --silksong-purple: #6b5b8c;
  --silksong-gold: #d4af37;
}

/* Main background */
ytd-app {
  background: linear-gradient(135deg, var(--silksong-dark-blue) 0%, var(--silksong-deep-blue) 50%, var(--silksong-green) 100%) !important;
  background-attachment: fixed !important;
}

/* Top navigation bar */
ytd-masthead,
#masthead-container {
  background: rgba(10, 22, 40, 0.95) !important;
  border-bottom: 2px solid var(--silksong-teal) !important;
  box-shadow: 0 4px 12px rgba(74, 124, 124, 0.3) !important;
}

/* Search bar */
#search-input,
#search input {
  background: var(--silksong-deep-blue) !important;
  border: 1px solid var(--silksong-teal) !important;
  color: var(--silksong-white) !important;
  border-radius: 20px !important;
}

#search-input::placeholder {
  color: var(--silksong-silver) !important;
  opacity: 0.7 !important;
}

/* Search button */
button#search-icon-legacy {
  background: var(--silksong-accent-blue) !important;
  border: 1px solid var(--silksong-teal) !important;
  border-radius: 0 20px 20px 0 !important;
}

button#search-icon-legacy:hover {
  background: var(--silksong-teal) !important;
}

/* Sidebar */
ytd-guide-renderer,
#guide-inner-content {
  background: rgba(26, 40, 69, 0.95) !important;
  border-right: 1px solid var(--silksong-teal) !important;
}

/* Sidebar items */
ytd-guide-entry-renderer,
ytd-guide-section-renderer {
  color: var(--silksong-silver) !important;
}

ytd-guide-entry-renderer:hover {
  background: var(--silksong-accent-blue) !important;
  border-left: 3px solid var(--silksong-gold) !important;
}

/* Video thumbnails */
ytd-thumbnail,
ytd-video-renderer,
ytd-grid-video-renderer {
  background: var(--silksong-deep-blue) !important;
  border: 1px solid var(--silksong-accent-blue) !important;
  border-radius: 8px !important;
  box-shadow: 0 2px 8px rgba(45, 74, 124, 0.4) !important;
}

ytd-thumbnail:hover {
  border-color: var(--silksong-teal) !important;
  box-shadow: 0 4px 16px rgba(74, 124, 124, 0.6) !important;
  transform: translateY(-2px) !important;
  transition: all 0.3s ease !important;
}

/* Video titles */
#video-title,
ytd-video-renderer #video-title {
  color: var(--silksong-white) !important;
  font-family: 'Cinzel', 'Trajan Pro', 'Georgia', serif !important;
  text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.8) !important;
}

#video-title:hover {
  color: var(--silksong-gold) !important;
}

/* Video metadata */
ytd-video-meta-block,
#metadata-line {
  color: var(--silksong-silver) !important;
}

/* Buttons */
yt-button-renderer,
ytd-button-renderer,
yt-icon-button {
  background: var(--silksong-accent-blue) !important;
  border: 1px solid var(--silksong-teal) !important;
  border-radius: 4px !important;
  color: var(--silksong-white) !important;
}

yt-button-renderer:hover,
ytd-button-renderer:hover {
  background: var(--silksong-teal) !important;
  box-shadow: 0 0 12px rgba(74, 124, 124, 0.6) !important;
}

/* Subscribe button */
.ytd-subscribe-button-renderer {
  background: var(--silksong-purple) !important;
  border: 1px solid var(--silksong-gold) !important;
  color: var(--silksong-white) !important;
  font-weight: bold !important;
}

.ytd-subscribe-button-renderer:hover {
  background: var(--silksong-gold) !important;
  color: var(--silksong-dark-blue) !important;
}

/* Video player background */
#player-container {
  background: var(--silksong-dark-blue) !important;
  border: 2px solid var(--silksong-teal) !important;
  border-radius: 8px !important;
  box-shadow: 0 8px 24px rgba(74, 124, 124, 0.4) !important;
}

/* Comments section */
ytd-comments,
#comments {
  background: var(--silksong-deep-blue) !important;
  border: 1px solid var(--silksong-accent-blue) !important;
  border-radius: 8px !important;
  padding: 16px !important;
}

ytd-comment-renderer {
  background: rgba(45, 74, 124, 0.3) !important;
  border-left: 2px solid var(--silksong-teal) !important;
  margin: 8px 0 !important;
  padding: 8px !important;
  border-radius: 4px !important;
}

/* Comment text */
#content-text {
  color: var(--silksong-silver) !important;
}

/* Input fields */
input[type="text"],
textarea {
  background: var(--silksong-deep-blue) !important;
  border: 1px solid var(--silksong-accent-blue) !important;
  color: var(--silksong-white) !important;
  border-radius: 4px !important;
}

input[type="text"]:focus,
textarea:focus {
  border-color: var(--silksong-teal) !important;
  box-shadow: 0 0 8px rgba(74, 124, 124, 0.5) !important;
}

/* Channel pages */
ytd-c4-tabbed-header-renderer {
  background: linear-gradient(180deg, var(--silksong-dark-blue) 0%, var(--silksong-deep-blue) 100%) !important;
  border-bottom: 2px solid var(--silksong-gold) !important;
}

/* Recommended videos */
#related {
  background: var(--silksong-deep-blue) !important;
  padding: 16px !important;
  border-radius: 8px !important;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 12px !important;
  background: var(--silksong-dark-blue) !important;
}

::-webkit-scrollbar-thumb {
  background: var(--silksong-accent-blue) !important;
  border: 1px solid var(--silksong-teal) !important;
  border-radius: 6px !important;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--silksong-teal) !important;
}

/* Chip bar (filters) */
yt-chip-cloud-chip-renderer {
  background: var(--silksong-accent-blue) !important;
  border: 1px solid var(--silksong-teal) !important;
  color: var(--silksong-white) !important;
}

yt-chip-cloud-chip-renderer[chip-style="STYLE_PRIMARY"] {
  background: var(--silksong-teal) !important;
  border-color: var(--silksong-gold) !important;
}

/* Bug motif decorations */
ytd-video-renderer::before {
  content: "?" !important;
  position: absolute !important;
  top: 4px !important;
  right: 4px !important;
  opacity: 0.15 !important;
  font-size: 24px !important;
  pointer-events: none !important;
}

/* Elegant hover effects */
* {
  transition: all 0.2s ease !important;
}

/* Text colors */
ytd-app,
yt-formatted-string,
span {
  color: var(--silksong-silver) !important;
}

h1, h2, h3 {
  color: var(--silksong-white) !important;
  font-family: 'Cinzel', 'Trajan Pro', 'Georgia', serif !important;
}

/* End of Hollow Knight Silksong Theme */
}
